@inherits UmbracoViewPage<BlogFrontPage>
@{
    Layout = null;
    var posts = Model.Children<BlogPost>();
}
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>@Model.Title</title>
    <link rel="stylesheet" href="~/dist/site.css" asp-append-version="true" />
</head>
<body class="bg-gray-50 text-gray-900 antialiased">
    <header class="bg-gradient-to-r from-blue-700 to-indigo-800 text-white py-16 px-4">
        <div class="max-w-4xl mx-auto text-center">
            <h1 class="text-4xl md:text-5xl font-extrabold tracking-tight">@Model.Title</h1>
            @if (!string.IsNullOrEmpty(Model.Intro))
            {
                <p class="mt-4 text-xl text-blue-100 leading-relaxed">@Model.Intro</p>
            }
        </div>
    </header>

    <main>
        @if (Model.Body?.Any() == true)
        {
            <section class="max-w-4xl mx-auto py-8">
                @await Html.GetBlockGridHtmlAsync(Model, "body")
            </section>
        }

        @if (posts?.Any() == true)
        {
            <section class="max-w-4xl mx-auto px-4 pb-16">
                <h2 class="text-2xl font-bold text-gray-800 mb-8 border-b pb-4">Latest Posts</h2>
                <div class="grid gap-8 md:grid-cols-2">
                    @foreach (var post in posts)
                    {
                        <article class="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden hover:shadow-md transition-shadow">
                            @if (post.ListingImage != null)
                            {
                                <a href="@post.Url()" class="block">
                                    <img src="@post.ListingImage.GetCropUrl(width: 600, height: 340)" alt="@post.Title" class="w-full h-48 object-cover" loading="lazy" />
                                </a>
                            }
                            <div class="p-6">
                                <time class="text-sm text-gray-500" datetime="@post.PublishDate.ToString("yyyy-MM-dd")">@post.PublishDate.ToString("MMMM d, yyyy")</time>
                                <h3 class="mt-2 text-xl font-semibold text-gray-900">
                                    <a href="@post.Url()" class="hover:text-blue-600 transition-colors">@post.Title</a>
                                </h3>
                                @if (!string.IsNullOrEmpty(post.Excerpt))
                                {
                                    <p class="mt-3 text-gray-600 leading-relaxed">@post.Excerpt</p>
                                }
                                <a href="@post.Url()" class="mt-4 inline-block text-blue-600 font-medium hover:text-blue-800 transition-colors">Read more &rarr;</a>
                            </div>
                        </article>
                    }
                </div>
            </section>
        }
    </main>

    <footer class="bg-gray-800 text-gray-400 py-8 text-center text-sm">
        <p>&copy; @DateTime.Now.Year MCP Blog. Powered by Umbraco.</p>
    </footer>
</body>
</html>

